 fg=set(shape); paint=set(); occ=0
 for r in range(len(data)-h+1):
  for c in range(len(data[0])-w+1):
   good=True
   for y in range(h):
    for x in range(w):
     v=data[r+y][c+x]
     if (y,x) in fg:
      if v!=0: good=False
     elif bg is not None and v!=bg: good=False
   if good:
    occ+=1;paint.update((r+y,c+x) for y,x in fg)
 return occ,paint
